import{_ as o,l,o as e,c as n,v as t,p as s,x as r,d,i as u,S as E}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"固定收益相对价值","description":"","frontmatter":{"title":"固定收益相对价值","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fi-relative-value.md","filePath":"quant/fi-relative-value.md","lastUpdated":1789023840000}'),p={name:"quant/fi-relative-value.md"};function h(c,a,f,B,_,m){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="固定收益相对价值" tabindex="-1">固定收益相对价值 <a class="header-anchor" href="#固定收益相对价值" aria-label="Permalink to &quot;固定收益相对价值&quot;">​</a></h1><div class="epigraph"><p>固收相对价值卖的是利差均值回复，买的是融资、基差与尾部相关；平静期像在压路机前捡硬币，压力期硬币和压路机一起砸过来。</p><footer>—— Duarte, Longstaff and Yu, Risk and Return in Fixed-Income Arbitrage, Review of Financial Studies, 2007</footer></div><p><a href="/quant/global-macro">上一课</a>的宏观常保留净方向：久期、美元、商品。固收相对价值（FI RV）的缺口是<strong>把方向对冲掉，只留曲线、基差与互换利差</strong>。主干 <a href="/quant/curve-butterfly">曲线蝶式</a>、<a href="/quant/ts-carry">期限结构 Carry</a>、<a href="/quant/cds-bond-basis">CDS–债券基差</a> 已写单条腿。本课给策略族位置：RV 是杠杆加约束的利差组合，不是「看对央行」的缩小版。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把国债、互换、MBS、期货 CTD 的价差当成无风险套利，忽略：融资（repo、保证金）、交割期权、凸性与违约相关。Duarte–Longstaff–Yu 把互换利差、收益曲线、抵押、波动等 RV 策略放到同一张风险–收益表上：平均收益来自承担难对冲的残差，不是来自免费午餐。问题是风险预算：RV 的夏普在低波动体制里好看，在 1998、2008、2020 年融资与相关同时坏掉。地图要按<strong>融资敏感 vs 曲率/波动敏感</strong>分桶，而不是按券种标签。</p><p>与宏观：同一基金里常混「曲线陡峭」（有净久期）和「蝶式中性」。报告必须拆开，否则宏观的方向会被叫做 RV 的 alpha。</p><h3 id="杠杆把利差分母变成危机分子" tabindex="-1">杠杆把利差分母变成危机分子 <a class="header-anchor" href="#杠杆把利差分母变成危机分子" aria-label="Permalink to &quot;杠杆把利差分母变成危机分子&quot;">​</a></h3><p>RV 的利差以基点计，要靠高杠杆才达到股权波动。杠杆的约束在 repo 与保证金，不在借券。利差走阔时，VAR 与 haircut 同向上升，被迫平仓把均值回复打断。这与股票多空的挤仓同构，工具不同。</p><p><span class="marginnote">LTCM 的教科书教训不是「不该做互换利差」，而是相关 1 与融资同时出现时，分散的 RV 桶并不是独立赌注。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分类：互换–国债利差、曲线杠铃/蝶式、期货基差与 CTD、MBS OAS 对冲、跨币种基差。每类写：对冲后剩余风险、融资链、容量。组合：用情景（融资消失、曲线扭转）而不是历史 \\(\\Sigma\\) 的 99%。执行：报价惯例与应计见主干报价课，不要用收盘中价回测。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无摩擦时，相近现金流的工具应由同一贴现核定价。摩擦（抵押品、资本、交割、流动性）打开基差。RV 赚的是摩擦补偿的一部分，付的是摩擦突然变大。宏观赚重估；RV 尽量对冲重估、暴露在摩擦上。拥挤时摩擦补偿被压薄，剩下的是尾部。</p>',13)),(e(),s(E,null,{default:r(()=>[u(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Spr%5B%22%E5%88%A9%E5%B7%AE%E4%B8%8E%E5%9F%BA%E5%B7%AE%22%5D%20--%3E%20Hdg%5B%22%E5%AF%B9%E5%86%B2%E6%96%B9%E5%90%91%20%E4%B9%85%E6%9C%9F%E6%B1%87%E7%8E%87%22%5D%0A%20%20Hdg%20--%3E%20Res%5B%22%E8%9E%8D%E8%B5%84%20%E6%9B%B2%E7%8E%87%20%E4%BA%A4%E5%89%B2%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20Fund%5B%22Repo%20%E4%B8%8E%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%20--%3E%20Res%0A%20%20Res%20--%3E%20Tail%5B%22%E4%BD%93%E5%88%B6%E7%9B%B8%E5%85%B3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写如何交易未公开的拍卖信息或操纵基准。新兴市场 RV 还有可兑换与 NDF，见宏观课边界。负基差「锁定」在融资消失时不是锁定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>固收 RV 是对冲方向后的利差与基差，风险在融资和尾部相关。</li><li>平静期夏普不可外推到杠杆去杠杆。</li><li>与宏观分报：净久期不是 RV。</li><li>出处：Duarte, Longstaff and Yu, <em>RFS</em>, 2007；单腿定价见曲线与 CDS 基差课。</li></ul>',4))])}const q=o(p,[["render",h]]);export{R as __pageData,q as default};
